set -euo pipefail
R=/dataset/shaoshitong/search-r1-rl/cosearch
test -z "$(squeue -h --name=cosearch-local-five -o %i)"
base64 -d > "$R/tools/gpu-ranker-l.bundle" <<'BUNDLE'

BUNDLE
cd "$R/repo"
test "$(git rev-parse --short HEAD)" = 409c0e5
git fetch "$R/tools/gpu-ranker-l.bundle" HEAD
git merge --ff-only FETCH_HEAD
test "$(git rev-parse --short HEAD)" = 9ee7528
cp reproduction/baselines/agent6-20261002/local_gpu_five.py "$R/tools/five_iteration_job_l.py"
"$R/env/bin/python" -m py_compile search_r1/baselines/cosearch.py reproduction/baselines/agent6-20261002/native_long_context_probe.py
PYTHONPATH="$R/tools/test-lib:$R/repo" "$R/env/bin/python" -m pytest -q tests/baselines/test_cosearch_context_evidence.py tests/baselines/test_cosearch_long_context_parity.py tests/baselines/test_cosearch_batch_parity.py tests/baselines/test_cosearch_parallel_loss.py
test ! -d "$R/runs/cosearch-local-gpu-five-20261003-l"
tmux new-session -d -s cosearch-local-gpu-five-l-20261003 "srun --immediate=60 -p gpu -w h100-16 -N1 --ntasks=1 --gres=gpu:h100:8 --exclusive --cpus-per-task=128 --mem=768G --job-name=cosearch-local-five env PYTHONPATH='$R/repo' COSEARCH_RUN_ID=cosearch-local-gpu-five-20261003-l '$R/env/bin/python' -m search_r1.baselines.preflight -- '$R/env/bin/python' '$R/tools/five_iteration_job_l.py' > '$R/logs/local-five-l.log' 2>&1"
sleep 3
squeue -h --name=cosearch-local-five -o '%i %T %N'
